const MAX_UPLOAD_BYTES=5*1024*1024,ALLOWED_IMAGE_TYPES={"image/png":"png","image/jpeg":"jpg","image/webp":"webp"};function safeHttpUrl(value){const raw=String(value||"").trim();if(!raw)return null;let u;try{u=new URL(raw)}catch{throw new Error("Image and website URLs must be complete HTTPS links.")}if(u.protocol!=="https:")throw new Error("Only HTTPS URLs are allowed.");return u.href}async function imageValue(file,url,folder){if(file?.size){if(!ALLOWED_IMAGE_TYPES[file.type])throw new Error("Upload a PNG, JPEG or WebP image only.");if(file.size>MAX_UPLOAD_BYTES)throw new Error("Images must be 5 MB or smaller.");return withBusy("Uploading image…",async()=>{const ext=ALLOWED_IMAGE_TYPES[file.type],path=`${state.session.user.id}/${folder}/${uid()}.${ext}`,bucket=window.MALFA_CMS.storageBucket||"league-media";const{error}=await client().storage.from(bucket).upload(path,file,{cacheControl:"3600",contentType:file.type,upsert:false});if(error)throw error;return client().storage.from(bucket).getPublicUrl(path).data.publicUrl})}return safeHttpUrl(url)}
