function resetNews(){$("#newsForm").reset();$("#newsForm [name=id]").value="";$("#newsForm [name=category]").value="Football News";$("#newsForm [name=slug]").dataset.touched=""}
async function saveNews(e){e.preventDefault();if(!guidedReadyToSave("news"))return;const d=new FormData(e.currentTarget),id=d.get("id");try{const image=await imageValue(d.get("image_file"),d.get("image_url"),"news"),published=d.get("published")==="on",payload={title:String(d.get("title")).trim(),slug:slugify(d.get("slug")),category:String(d.get("category")||"Football News").trim(),competition_id:d.get("competition_id")||null,club_id:d.get("club_id")||null,excerpt:String(d.get("excerpt")||"").trim()||null,body:String(d.get("body")||"").trim()||null,image_url:image,published,published_at:published?new Date().toISOString():null,updated_at:new Date().toISOString()};await saveEntity("news_posts",payload,id||null);notice(id?"News updated.":"News added.");cancelGuidedFlow("news");await loadAll()}catch(err){notice(friendlyError(err),"error")}}
async function removeNews(id){if(!confirm("Delete this story?"))return;try{await deleteEntity("news_posts",id);notice("News deleted.");await loadAll()}catch(err){notice(friendlyError(err),"error")}}
function renderCompetitions(type){const mount=type==="league"?$("#divisionAdminList"):$("#tournamentAdminList");mount.innerHTML=state.competitions.filter(c=>c.type===type).sort((a,b)=>num(a.sort_order)-num(b.sort_order)).map(c=>`<article class="admin-list-item"><span class="admin-thumb-placeholder">${esc(c.short_name)}</span><div><span class="badge">${c.visible?"Public":"Hidden"} · ${c.active?"Active":"Inactive"}</span><h3>${esc(c.name)}</h3><p>${esc(c.category||type)}</p></div><div class="admin-actions"><button type="button" class="button secondary small" data-edit-comp="${c.id}" data-type="${type}">Edit</button><button type="button" class="button danger small" data-delete-comp="${c.id}">Delete</button></div></article>`).join("")||'<p class="muted">No competitions yet.</p>';$$('[data-edit-comp]',mount).forEach(b=>b.onclick=()=>editCompetition(b.dataset.editComp,b.dataset.type));$$('[data-delete-comp]',mount).forEach(b=>b.onclick=()=>removeCompetition(b.dataset.deleteComp))}
function editCompetition(id,type){const x=comp(id),flowName=type==="league"?"division":"tournament",f=$(type==="league"?"#divisionForm":"#tournamentForm");if(!x)return;resetCompetition(flowName);f.elements.original_id.value=x.id;["id","name","short_name","category","sort_order","accent","description"].forEach(k=>f.elements[k].value=x[k]??"");f.elements.visible.checked=x.visible!==false;f.elements.active.checked=x.active!==false;openGuidedFlow(flowName,"edit",x.name)}
function resetCompetition(type){const f=$(type==="division"?"#divisionForm":"#tournamentForm");f.reset();f.elements.original_id.value="";f.elements.sort_order.value=type==="division"?100:200;f.elements.accent.value="#d8202f";f.elements.active.checked=true;f.elements.visible.checked=type==="division"}
async function saveCompetition(e,type){e.preventDefault();const flowName=type==="league"?"division":"tournament";if(!guidedReadyToSave(flowName))return;const d=new FormData(e.currentTarget),original=d.get("original_id"),id=slugify(d.get("id")),payload={id,slug:id,name:String(d.get("name")).trim(),short_name:String(d.get("short_name")).trim(),category:String(d.get("category")||"").trim(),type,description:String(d.get("description")||"").trim()||null,accent:d.get("accent")||"#d8202f",sort_order:num(d.get("sort_order")),visible:d.get("visible")==="on",active:d.get("active")==="on",updated_at:new Date().toISOString()};if(original&&original!==id)return notice("Competition IDs cannot be changed after creation. Create a new competition instead.","error");try{await saveEntity("competitions",payload,original||null);notice(`${type==="league"?"Division":"Tournament"} saved.`);cancelGuidedFlow(flowName);await loadAll()}catch(err){notice(friendlyError(err),"error")}}
async function removeCompetition(id){if(!confirm("Delete this competition and related entries?"))return;try{await deleteEntity("competitions",id);notice("Competition deleted.");await loadAll()}catch(err){notice(friendlyError(err),"error")}}
function renderPartners(){$("#partnerAdminList").innerHTML=state.partners.map(p=>`<article class="admin-list-item">${p.logo_url?`<img src="${esc(p.logo_url)}" alt="">`:'<span class="admin-thumb-placeholder">PART</span>'}<div><span class="badge">${esc(p.tier||"Partner")} · ${p.active?"Public":"Hidden"}</span><h3>${esc(p.name)}</h3><p>${esc(p.website||"")}</p></div><div class="admin-actions"><button type="button" class="button secondary small" data-edit-partner="${p.id}">Edit</button><button type="button" class="button danger small" data-delete-partner="${p.id}">Delete</button></div></article>`).join("")||'<p class="muted">No partners yet.</p>';$$('[data-edit-partner]').forEach(b=>b.onclick=()=>editPartner(b.dataset.editPartner));$$('[data-delete-partner]').forEach(b=>b.onclick=()=>removePartner(b.dataset.deletePartner))}
function editPartner(id){const x=state.partners.find(p=>p.id===id),f=$("#partnerForm");if(!x)return;resetPartner();["id","name","tier","display_order","logo_url","website","description"].forEach(k=>f.elements[k].value=x[k]??"");f.elements.active.checked=x.active!==false;openGuidedFlow("partner","edit",x.name)}
function resetPartner(){$("#partnerForm").reset();$("#partnerForm [name=id]").value="";$("#partnerForm [name=active]").checked=true}
async function savePartner(e){e.preventDefault();if(!guidedReadyToSave("partner"))return;const d=new FormData(e.currentTarget),id=d.get("id");try{const logo=await imageValue(d.get("logo_file"),d.get("logo_url"),"partners"),payload={name:String(d.get("name")).trim(),tier:d.get("tier"),display_order:num(d.get("display_order")),logo_url:logo,website:String(d.get("website")||"").trim()||null,description:String(d.get("description")||"").trim()||null,active:d.get("active")==="on",updated_at:new Date().toISOString()};await saveEntity("partners",payload,id||null);notice(id?"Partner updated.":"Partner added.");cancelGuidedFlow("partner");await loadAll()}catch(err){notice(friendlyError(err),"error")}}
async function removePartner(id){if(!confirm("Delete this partner?"))return;try{await deleteEntity("partners",id);notice("Partner deleted.");await loadAll()}catch(err){notice(friendlyError(err),"error")}}
// Defer database work until Supabase releases the authentication callback lock.
function scheduleSession(s){setTimeout(()=>session(s).catch(err=>{state.adminRole=null;$("#dashboard").hidden=true;$("#loginPanel").hidden=false;notice(friendlyError(err,"Unable to verify administrator access."),"error")}),0)}
const ADMIN_TABS={super_admin:["overview","matches","tables","clubs","news","divisions","tournaments","partners","access"],league_admin:["overview","matches","tables","news"],club_admin:["overview","clubs","news"]};
function allowedTab(name){return (ADMIN_TABS[state.adminRole]||[]).includes(name)}
function validScore(value){return typeof value==="number"&&Number.isInteger(value)&&value>=0}
function resetAccessForm(){const form=$("#accessForm");state.editingAdminId=null;form.reset();form.elements.email.readOnly=false;$("#accessFormTitle").textContent="Grant administrator access";$("#saveAccessButton").textContent="Grant access";$$('[name=competition_ids],[name=club_ids]',form).forEach(i=>i.checked=false);renderAccessScopes()}
function editAccess(id){
  if(state.adminRole!=="super_admin")return;
  const admin=state.admins.find(a=>a.user_id===id);if(!admin)return;
  const form=$("#accessForm");state.editingAdminId=id;form.elements.email.value=admin.email;form.elements.email.readOnly=true;form.elements.role.value=admin.role;
  $$("[name=competition_ids]",form).forEach(i=>i.checked=(admin.competition_ids||[]).includes(i.value));
  $$("[name=club_ids]",form).forEach(i=>i.checked=(admin.club_ids||[]).includes(i.value));
  $("#accessFormTitle").textContent=`Edit ${admin.email}`;$("#saveAccessButton").textContent="Update access";renderAccessScopes();form.scrollIntoView({behavior:"smooth"});notice("Administrator access loaded for editing.","info");
}
function bindAudit(){
  const panel=$('[data-panel="access"]');
  panel.insertAdjacentHTML("beforeend",'<section class="admin-card"><h2>Recent activity</h2><p class="muted">The latest 50 recorded changes. Only superadmins can view this history.</p><button type="button" class="button secondary" id="loadAudit">Load activity</button><div id="auditList" class="admin-list" aria-live="polite"></div></section>');
  $("#loadAudit").addEventListener("click",loadAudit);
}
async function loadAudit(){
  if(state.adminRole!=="super_admin")return;
  const button=$("#loadAudit"),mount=$("#auditList");button.disabled=true;
  try{
    const {data,error}=await client().from("content_audit_log").select("id,occurred_at,actor_id,action,table_name,record_key").order("id",{ascending:false}).limit(50);
    if(error)throw error;
    if(state.adminRole!=="super_admin")return;
    mount.innerHTML=(data||[]).map(row=>{const actor=state.admins.find(a=>a.user_id===row.actor_id);return `<article class="admin-list-item"><div><h3>${esc(row.action)} · ${esc(row.table_name)}</h3><p>${esc(fmt(row.occurred_at))} · ${esc(actor?.email||row.actor_id||"Database operation")}</p><small>${esc(row.record_key||"")}</small></div></article>`}).join("")||'<p class="muted">No activity recorded yet.</p>';
  }catch(err){notice(friendlyError(err,"Unable to load activity."),"error")}finally{button.disabled=false}
}
document.addEventListener("DOMContentLoaded",init);
